def extend(styles,families):
 import json,unicodedata
 from pathlib import Path
 from product_styles import LOCK,AUDIO
 def slug(name):return '-'.join(''.join(c for c in unicodedata.normalize('NFKD',name.lower()) if not unicodedata.combining(c)).split())
